"use client";

import Link from "next/link";
import { useParams } from "next/navigation";
import { useState } from "react";
import { api } from "@/lib/api";

type FormState = "idle" | "loading" | "success" | "error";

interface ResetPasswordResponse {
  success: boolean;
  message: string;
  data: null;
  errors?: Record<string, string[]>;
}

export default function ResetPasswordPage() {
  const params = useParams<{ token: string }>();
  const token = params?.token;

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [formState, setFormState] = useState<FormState>("idle");
  const [errors, setErrors] = useState<{ email?: string; password?: string; confirm?: string; form?: string }>({});

  const strength = getStrength(password);

  function validate() {
    const errs: typeof errors = {};
    if (!email.trim()) errs.email = "Email is required.";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errs.email = "Enter a valid email address.";
    if (!password) errs.password = "Password is required.";
    else if (password.length < 8) errs.password = "Must be at least 8 characters.";
    if (!confirm) errs.confirm = "Please confirm your password.";
    else if (confirm !== password) errs.confirm = "Passwords do not match.";
    return errs;
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const errs = validate();
    if (Object.keys(errs).length) {
      setErrors(errs);
      return;
    }

    setErrors({});
    setFormState("loading");

    try {
      const res = await api.post<ResetPasswordResponse>(`/reset-password/${token}`, {
        email,
        password,
        password_confirmation: confirm,
      });

      if (!res.success) {
        throw new Error(
          res.errors?.password?.[0] ||
            res.errors?.token?.[0] ||
            res.errors?.email?.[0] ||
            res.message ||
            "Unable to reset password."
        );
      }

      setFormState("success");
    } catch (err: unknown) {
      setFormState("error");
      setErrors((prev) => ({
        ...prev,
        form: err instanceof Error ? err.message : "Unable to reset password.",
      }));
    }
  }

  if (!token) {
    return <TokenErrorScreen expired={false} />;
  }

  return (
    <div className="page-shell min-h-screen flex items-center justify-center p-4" style={{ background: "var(--color-bg)" }}>
      <div className="w-full max-w-sm relative animate-fade-in">
        <div className="text-center mb-8">
          <h1 className="text-xl font-semibold" style={{ color: "var(--color-text)" }}>
            {formState === "success" ? "Password updated" : "Set a new password"}
          </h1>
          <p className="text-sm mt-1.5" style={{ color: "var(--color-text-secondary)" }}>
            {formState === "success" ? "Your password has been reset successfully." : "Use the same email that requested this reset link."}
          </p>
        </div>

        <div className="card card-body">
          {formState === "success" ? (
            <div className="space-y-5">
              <div className="rounded-xl p-4 text-sm" style={{ background: "var(--color-primary-muted)", color: "var(--color-primary-dark)" }}>
                Password changed. You can now log in with your new password.
              </div>
              <Link href="/" className="btn btn-primary btn-full">
                Go to Login
              </Link>
            </div>
          ) : (
            <form onSubmit={handleSubmit} noValidate className="space-y-5">
              {errors.form && <p className="form-error">{errors.form}</p>}

              <div className="form-group">
                <label htmlFor="email" className="form-label">Email</label>
                <input
                  id="email"
                  type="email"
                  autoComplete="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  disabled={formState === "loading"}
                  style={errors.email ? { borderColor: "var(--color-error)" } : {}}
                />
                {errors.email && <p className="form-error mt-1">{errors.email}</p>}
              </div>

              <div className="form-group">
                <label htmlFor="password" className="form-label">New Password</label>
                <div className="input-icon-wrapper">
                  <input
                    id="password"
                    type={showPassword ? "text" : "password"}
                    autoComplete="new-password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="input-has-right-icon"
                    disabled={formState === "loading"}
                    style={errors.password ? { borderColor: "var(--color-error)" } : {}}
                  />
                  <button type="button" className="input-icon-right" onClick={() => setShowPassword((v) => !v)}>
                    {showPassword ? "Hide" : "Show"}
                  </button>
                </div>
                {errors.password && <p className="form-error mt-1">{errors.password}</p>}
                {password.length > 0 && <p className="text-xs mt-1">{strength.label}</p>}
              </div>

              <div className="form-group">
                <label htmlFor="confirm" className="form-label">Confirm Password</label>
                <div className="input-icon-wrapper">
                  <input
                    id="confirm"
                    type={showConfirm ? "text" : "password"}
                    autoComplete="new-password"
                    value={confirm}
                    onChange={(e) => setConfirm(e.target.value)}
                    className="input-has-right-icon"
                    disabled={formState === "loading"}
                    style={errors.confirm ? { borderColor: "var(--color-error)" } : {}}
                  />
                  <button type="button" className="input-icon-right" onClick={() => setShowConfirm((v) => !v)}>
                    {showConfirm ? "Hide" : "Show"}
                  </button>
                </div>
                {errors.confirm && <p className="form-error mt-1">{errors.confirm}</p>}
              </div>

              <button type="submit" className="btn btn-primary btn-full" disabled={formState === "loading"}>
                {formState === "loading" ? "Updating password..." : "Reset Password"}
              </button>
            </form>
          )}
        </div>

        <p className="text-center text-sm mt-5" style={{ color: "var(--color-text-muted)" }}>
          <Link href="/" style={{ color: "var(--color-primary-light)" }} className="font-medium">
            Back to login
          </Link>
        </p>
      </div>
    </div>
  );
}

function TokenErrorScreen({ expired }: { expired: boolean }) {
  return (
    <div className="page-shell min-h-screen flex items-center justify-center p-4" style={{ background: "var(--color-bg)" }}>
      <div className="w-full max-w-sm animate-fade-in text-center">
        <h1 className="text-xl font-semibold mb-2" style={{ color: "var(--color-text)" }}>
          {expired ? "Link has expired" : "Invalid reset link"}
        </h1>
        <p className="text-sm mb-6" style={{ color: "var(--color-text-secondary)" }}>
          This reset link is invalid or unavailable.
        </p>
        <div className="card card-body space-y-3">
          <Link href="/forgot-password" className="btn btn-primary btn-full">Request a new link</Link>
          <Link href="/" className="btn btn-ghost btn-full">Back to login</Link>
        </div>
      </div>
    </div>
  );
}

function getStrength(pw: string): { score: number; label: string } {
  if (!pw) return { score: 0, label: "" };
  let score = 0;
  if (pw.length >= 8) score++;
  if (/[0-9]/.test(pw)) score++;
  if (/[^a-zA-Z0-9]/.test(pw)) score++;
  if (pw.length >= 12) score++;
  const labels = ["", "Weak", "Fair", "Good", "Strong"];
  return { score, label: labels[score] ?? "Strong" };
}
